/* LUMIO community extension — all writes go through Supabase RLS. */
const cEsc=safeText;
function cOpen(html){document.getElementById('communityContent').innerHTML=html;document.getElementById('communityOverlay').hidden=false;document.body.style.overflow='hidden'}
function cClose(){document.getElementById('communityOverlay').hidden=true;document.body.style.overflow=''}
function cHeader(title){return `<button class="secondary" onclick="cClose()">← Назад</button><h1>${cEsc(title)}</h1>`}
function cRequire(){if(!viewer){showLogin();toast('Войдите или зарегистрируйтесь');return false}if(!db){toast('Сервис временно недоступен');return false}return true}
function openSubmission(){if(!cRequire())return;closeProfile();cOpen(cHeader('Добавить фильм или сериал')+`<div class="communityNotice"><b>Как создать карточку</b><br>Сначала отправьте фильм или сериал на модерацию. После публикации можно будет создавать карточки актёров, режиссёров и других участников команды. Редактировать созданную карточку человека может только её автор. При этом каждый пользователь может найти уже существующего человека и добавить его в свой фильм или сериал.</div><form onsubmit="sendSubmission(event)"><label>Название *</label><input name="t" required maxlength="160"><label>Дополнительное название</label><input name="altTitle" maxlength="160"><div class="row"><div><label>Тип</label><select name="type"><option value="movie">Фильм</option><option value="series">Сериал</option></select></div><div><label>Год</label><input type="number" name="y" min="1880" max="2100" value="2026"></div></div><label>Жанр</label><input name="g" maxlength="100"><label>Описание *</label><textarea name="d" minlength="20" maxlength="5000" required></textarea><label>Постер — файл или прямая HTTPS-ссылка</label><input type="file" id="submitPoster" accept="image/jpeg,image/png,image/webp"><input name="p" placeholder="https://...jpg"><label>Трейлер — файл или ссылка VK Видео</label><input type="file" id="submitTrailer" accept="video/mp4,video/webm"><input name="trailer" placeholder="https://vkvideo.ru/video..."><label>Полный фильм (VK Видео или MP4)</label><input name="video" placeholder="https://..."><label>Кинопоиск</label><input name="kinopoisk" placeholder="https://www.kinopoisk.ru/..."><label>IMDb</label><input name="imdb" placeholder="https://www.imdb.com/..."><label>RVKINO</label><input name="rvkino" placeholder="https://rvkino.ru/..."><p id="submitStatus" role="status"></p><button class="primary" type="submit">Отправить на модерацию</button></form>`)}
async function communityUpload(file,folder){if(!file)return '';let types=folder==='posters'?['image/jpeg','image/png','image/webp']:['video/mp4','video/webm'];if(!types.includes(file.type))throw Error('Неподдерживаемый формат');if(file.size>(folder==='posters'?10:150)*1024*1024)throw Error('Файл слишком большой');let ext=file.name.split('.').pop().toLowerCase();let path=`submissions/${viewer.id}/${folder}/${crypto.randomUUID()}.${ext}`;let {error}=await db.storage.from('media').upload(path,file,{contentType:file.type});if(error)throw error;return db.storage.from('media').getPublicUrl(path).data.publicUrl}
async function sendSubmission(e){e.preventDefault();if(!cRequire())return;let btn=e.target.querySelector('[type=submit]'),status=document.getElementById('submitStatus');btn.disabled=true;status.textContent='Отправляем заявку…';try{let data=Object.fromEntries(new FormData(e.target).entries());for(let k of ['p','trailer','video','kinopoisk','imdb','rvkino'])if(data[k]&&!/^https:\/\//i.test(data[k]))throw Error('Укажите HTTPS-ссылку в поле '+k);let pf=document.getElementById('submitPoster').files[0],tf=document.getElementById('submitTrailer').files[0];if(pf)data.p=await communityUpload(pf,'posters');if(tf)data.trailer=await communityUpload(tf,'trailers');data.y=Number(data.y)||2026;data.credits=[];let {error}=await db.from('submissions').insert({user_id:viewer.id,data,status:'pending'});if(error)throw error;cOpen(cHeader('Заявка отправлена')+'<p>Спасибо! Фильм появится в каталоге после проверки редактором.</p><button class="primary" onclick="openMySubmissions()">Мои заявки</button>')}catch(err){status.textContent='Ошибка: '+err.message;btn.disabled=false}}
async function openMySubmissions(){if(!cRequire())return;let {data,error}=await db.from('submissions').select('id,data,status,created_at,moderation_note').eq('user_id',viewer.id).order('created_at',{ascending:false});if(error)return toast('Не удалось загрузить заявки');let {data:ownedFilms}=await db.from('catalog').select('id,data').filter('data->>submitted_by','eq',viewer.id);let filmByTitle=new Map((ownedFilms||[]).map(f=>[f.data.t,f.id]));let names={pending:'На проверке',approved:'Опубликовано',rejected:'Отклонено'};cOpen(cHeader('Мои заявки')+(data.length?data.map(x=>`<div class="communityNotice"><b>${cEsc(x.data.t)}</b><p>${names[x.status]||x.status}</p>${x.moderation_note?`<small>${cEsc(x.moderation_note)}</small>`:''}${x.status==='approved'&&filmByTitle.has(x.data.t)?`<p><button class="secondary" onclick="managePeople(${filmByTitle.get(x.data.t)})">Актёры и создатели</button></p>`:''}</div>`).join(''):'<p>Заявок пока нет.</p>')+'<button class="primary" onclick="openSubmission()">＋ Добавить проект</button>')}
async function moderationSubmissions(){if(!isAdmin)return toast('Нет доступа');let {data,error}=await db.from('submissions').select('id,user_id,data,status,created_at').order('created_at',{ascending:false}).limit(200);if(error)return toast('Не удалось загрузить заявки');document.getElementById('adminContent').innerHTML=`<button class="adminBtn" onclick="adminList()">← К каталогу</button><h1>Заявки пользователей</h1>`+(data.map(x=>`<div class="adminReview"><b>${cEsc(x.data.t)} · ${x.data.type==='series'?'Сериал':'Фильм'}</b><p>${cEsc(x.data.d||'')}</p><small>${cEsc(x.status)}</small><div>${x.status==='pending'?`<button class="adminBtn primaryA" onclick="moderateSubmission(${x.id},'approved')">Опубликовать</button><button class="adminBtn danger" onclick="moderateSubmission(${x.id},'rejected')">Отклонить</button>`:''}</div></div>`).join('')||'<p>Заявок нет.</p>')}
async function moderateSubmission(id,action){if(!isAdmin)return;let note=action==='rejected'?prompt('Причина отклонения (необязательно)')||'':'';let {error}=await db.rpc('moderate_submission',{submission_id:id,decision:action,note});if(error)return toast('Ошибка: '+error.message);await syncCatalog();await moderationSubmissions()}
// Add moderation action without changing the existing admin layout.
const v7AdminList=adminList;adminList=function(q=''){v7AdminList(q);let bar=document.querySelector('#adminContent .adminToolbar');if(bar&&!bar.querySelector('#submissionsBtn'))bar.insertAdjacentHTML('beforeend','<button class="adminBtn" id="submissionsBtn" onclick="moderationSubmissions()">📥 Заявки пользователей</button>')};
function contactPage(){cOpen(cHeader('Контакты')+'<p>По вопросам сотрудничества и PR</p><p><a href="mailto:pr@lumio.example">pr@lumio.example</a></p><h2>Редакция</h2><p>Предложения по каталогу, публикации и материалам</p><p><a href="mailto:editor@lumio.example">editor@lumio.example</a></p><small>Контакты временные. Адреса в зоне .example не принимают письма.</small>')}
function aboutPage(){cOpen(cHeader('О проекте LUMIO')+'<p>LUMIO — онлайн-кинотеатр, который развивается с 2026 года. Мы создаём удобное пространство для знакомства с фильмами и сериалами, поддерживаем авторов и стремимся собирать качественные истории в одном месте.</p><p>Наша цель — помогать зрителям находить интересное кино, открывать новые имена и делиться впечатлениями. Карточки проектов проходят редакционную проверку, а отзывы публикуются после модерации.</p><p>Каталог развивается вместе с авторами и зрителями. Возможность просмотра зависит от наличия прав и доступности видео.</p>')}
function addFooterLinks(){let f=document.querySelector('footer');if(f&&!document.getElementById('communityFooter'))f.insertAdjacentHTML('beforeend','<div id="communityFooter" style="margin-top:24px;display:flex;gap:18px;flex-wrap:wrap"><button class="secondary" onclick="aboutPage()">О проекте</button><button class="secondary" onclick="contactPage()">Контакты</button></div>')}
// The trailer occupies the top media area of a detail page whenever it exists.
const v7OpenDetail=openDetail;openDetail=function(id){v7OpenDetail(id);let x=get(id),slot=document.getElementById('detailTrailerBanner');slot.innerHTML='';slot.hidden=true;if(x?.trailer){let vk=vkEmbed(x.trailer);if(vk){let iframe=document.createElement('iframe');iframe.src=vk;iframe.title='Трейлер';iframe.loading='lazy';iframe.allow='autoplay; fullscreen; picture-in-picture';iframe.allowFullscreen=true;slot.appendChild(iframe);slot.hidden=false}else if(/^https:\/\//.test(x.trailer)&&/\.(mp4|webm)(\?|$)/i.test(x.trailer)){let v=document.createElement('video');v.src=x.trailer;v.controls=true;v.preload='none';v.playsInline=true;slot.appendChild(v);slot.hidden=false}}document.getElementById('detailArt').hidden=!slot.hidden;renderPeople(x)};
function renderPeople(x){let box=document.getElementById('communityPeople');if(!box){box=document.createElement('section');box.id='communityPeople';document.querySelector('.detailContent')?.appendChild(box)}box.innerHTML='<h2>Актёры и создатели</h2><div id="peopleList">Загрузка…</div>';if(!db){box.innerHTML='';return}db.from('film_people').select('role,person_id,people(id,name)').eq('film_id',x.id).then(({data,error})=>{let target=document.getElementById('peopleList');if(!target||currentId!==x.id)return;let legacy=(x.credits||[]).map(n=>`<span class="personChip">${cEsc(n)}</span>`).join('');target.innerHTML=(data||[]).map(r=>`<button class="personChip" onclick="openPerson(${r.person_id})">${cEsc(r.people?.name||'')} · ${cEsc(r.role)}</button>`).join('')||legacy||'<p>Состав команды пока не указан.</p>'})}
async function openPerson(id){if(!db)return;let {data:p,error}=await db.from('people').select('id,name,bio,created_by').eq('id',id).single();if(error)return toast('Карточка не найдена');let {data:roles}=await db.from('film_people').select('role,film_id').eq('person_id',id);cOpen(cHeader(p.name)+`<p>${cEsc(p.bio||'Биография пока не добавлена.')}</p><h2>Фильмография</h2>`+(roles||[]).map(r=>`<button class="personChip" onclick="cClose();openDetail(${r.film_id})">${cEsc(get(r.film_id)?.t||'Проект')} — ${cEsc(r.role)}</button>`).join('')+((viewer?.id===p.created_by||isAdmin)?`<p><button class="secondary" onclick="editPerson(${id})">Редактировать карточку</button></p>`:''))}
async function editPerson(id){if(!cRequire())return;let {data:p,error}=await db.from('people').select('*').eq('id',id).single();if(error||!(p.created_by===viewer.id||isAdmin))return toast('Нет прав');cOpen(cHeader('Редактировать участника')+`<form onsubmit="savePerson(event,${id})"><label>Имя</label><input name="name" required value="${cEsc(p.name)}"><label>Биография</label><textarea name="bio">${cEsc(p.bio||'')}</textarea><button class="primary">Сохранить</button></form>`)}
async function savePerson(e,id){e.preventDefault();let {error}=await db.from('people').update({name:e.target.elements.name.value,bio:e.target.elements.bio.value}).eq('id',id);if(error)return toast(error.message);openPerson(id)}
async function managePeople(filmId){if(!cRequire())return;let film=get(filmId);if(!film)return;let {data:owned}=await db.from('catalog').select('id').eq('id',filmId).filter('data->>submitted_by','eq',viewer.id).maybeSingle();if(!owned&&!isAdmin)return toast('Редактировать команду может только автор фильма');cOpen(cHeader('Команда: '+film.t)+`<div class="communityNotice">Создать новую карточку человека можно после публикации фильма. Изменять её сможет автор карточки; добавлять человека в свои фильмы смогут все авторы.</div><form onsubmit="createPerson(event,${filmId})"><label>Создать карточку человека</label><input name="name" required placeholder="Имя и фамилия"><button class="primary">Создать</button></form><h2>Найти участника</h2><input id="peopleSearch" oninput="searchPeople(this.value,${filmId})" placeholder="Имя актёра или режиссёра"><div id="peopleResults"></div>`);searchPeople('',filmId)}
async function createPerson(e,filmId){e.preventDefault();let {data,error}=await db.from('people').insert({name:e.target.elements.name.value.trim(),created_by:viewer.id}).select('id').single();if(error)return toast(error.message);await linkPerson(data.id,filmId)}
async function searchPeople(q,filmId){let query=db.from('people').select('id,name').order('name').limit(30);if(q)query=query.ilike('name','%'+q.replace(/[%_]/g,'')+'%');let {data}=await query;let box=document.getElementById('peopleResults');if(box)box.innerHTML=(data||[]).map(p=>`<button class="personChip" onclick="linkPerson(${p.id},${filmId})">＋ ${cEsc(p.name)}</button>`).join('')||'<p>Никого не найдено</p>'}
async function linkPerson(personId,filmId){let role=prompt('Должность (актёр, режиссёр, сценарист и т. д.)','Актёр');if(!role)return;let {error}=await db.from('film_people').insert({film_id:filmId,person_id:personId,role:role.slice(0,100)});if(error)return toast(error.message);toast('Добавлено в команду');managePeople(filmId)}
// Allow the submitting author to attach existing people to their published film.
const v7AdminEdit=adminEdit;adminEdit=function(id){v7AdminEdit(id);if(id!=null){document.querySelector('#adminFilmForm')?.insertAdjacentHTML('afterend',`<button class="adminBtn" onclick="managePeople(${id})">Актёры и съёмочная группа</button>`)}};
const v7Boot=()=>{addFooterLinks();let sel=document.getElementById('reviewScore');if(sel)for(let o of sel.options)o.textContent=o.value;let img=document.getElementById('heroImage');if(img){let observer=new MutationObserver(()=>{img.classList.remove('heroZoom');requestAnimationFrame(()=>img.classList.add('heroZoom'))});observer.observe(img,{attributes:true,attributeFilter:['src']})}};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',v7Boot);else v7Boot();
